async Task DemoAsync()
{
    Console.WriteLine("A");      // right away, on the calling thread
    await Task.Delay(100);       // a real pause: the method returned a Task
    Console.WriteLine("C");      // the continuation, later
}
var t = DemoAsync();             // A has been printed
Console.WriteLine("B");
await t;                         // C

